package net.civeira.phylax.feature.observe.observedprobe.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.observe.observedprobe.domain.ObservedProbe;
import net.civeira.phylax.feature.observe.observedprobe.domain.valueobject.ConsecutiveFailuresVO;

class ConsecutiveFailuresValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of consecutive failures of observed probe")
  void test_consecutive_failures_value_holder_assign_plain_value() {
    Object holder = new Object();
    ConsecutiveFailuresValueHolder<Object> value = new ConsecutiveFailuresValueHolder<>(holder);
    Assertions.assertSame(holder, value.consecutiveFailures(1), "Setters must return the holder");
    Assertions.assertTrue(value.getConsecutiveFailuresValue().isPresent(),
        "The plain value must be stored");
    Assertions.assertEquals(1, value.getConsecutiveFailures().orElse(null),
        "The plain value must be recovered");
    Assertions.assertSame(holder, value.consecutiveFailuresNull(),
        "Setters must return the holder");
    Assertions.assertTrue(value.getConsecutiveFailuresValue().isPresent(),
        "A null value object must be stored");
    Assertions.assertFalse(value.getConsecutiveFailures().isPresent(),
        "A null value must not have content");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of consecutive failures of observed probe")
  void test_consecutive_failures_value_holder_assign_value_object() {
    Object holder = new Object();
    ConsecutiveFailuresValueHolder<Object> value = new ConsecutiveFailuresValueHolder<>(holder);
    ConsecutiveFailuresVO vo = ConsecutiveFailuresVO.from(1);
    Assertions.assertFalse(value.getConsecutiveFailuresValue().isPresent(),
        "A new holder must be empty");
    Assertions.assertSame(holder, value.consecutiveFailures(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getConsecutiveFailuresValue().orElseThrow());
    Assertions.assertSame(holder, value.consecutiveFailures(Optional.empty()));
    Assertions.assertFalse(value.getConsecutiveFailuresValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.consecutiveFailures(Optional.of(vo)));
    Assertions.assertSame(vo, value.getConsecutiveFailuresValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of consecutive failures of observed probe against the original")
  void test_consecutive_failures_value_holder_read() {
    Object holder = new Object();
    ConsecutiveFailuresValueHolder<Object> value = new ConsecutiveFailuresValueHolder<>(holder);
    ConsecutiveFailuresVO vo = ConsecutiveFailuresVO.from(1);
    ConsecutiveFailuresVO other = ConsecutiveFailuresVO.from(1);
    ObservedProbe original = Mockito.mock(ObservedProbe.class);
    Mockito.when(original.getConsecutiveFailuresValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readConsecutiveFailures(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNotNull(value.readConsecutiveFailures(Optional.empty(), fails),
        "Without value and original a null value is returned");
    Assertions.assertTrue(fails.isEmpty(), "An optional value is never reported as missing");
    value.consecutiveFailures(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readConsecutiveFailures(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readConsecutiveFailures(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of consecutive failures of observed probe")
  void test_consecutive_failures_value_holder_unset() {
    Object holder = new Object();
    ConsecutiveFailuresValueHolder<Object> value = new ConsecutiveFailuresValueHolder<>(holder);
    ConsecutiveFailuresVO vo = ConsecutiveFailuresVO.from(1);
    value.consecutiveFailures(vo);
    Assertions.assertSame(holder,
        value.unsetConsecutiveFailuresIfMatches("consecutiveFailures_other"));
    Assertions.assertTrue(value.getConsecutiveFailuresValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetConsecutiveFailuresIfMatches("consecutiveFailures"));
    Assertions.assertFalse(value.getConsecutiveFailuresValue().isPresent(),
        "The field name must clear the value");
    value.consecutiveFailures(vo);
    Assertions.assertSame(holder, value.unsetConsecutiveFailures());
    Assertions.assertFalse(value.getConsecutiveFailuresValue().isPresent(),
        "Unset must clear the value");
  }
}
